import { render, screen, fireEvent } from '@testing-library/react';
import { describe, it, expect, vi } from 'vitest';
import { BookCard } from './BookCard';

const book = {
  id: 'b1',
  title: 'The Great Gatsby',
  author: 'F. Scott Fitzgerald',
  status: 'to-read' as const,
};

describe('BookCard', () => {
  it('renders title', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    expect(screen.getByRole('heading', { name: 'The Great Gatsby' })).toBeInTheDocument();
  });

  it('renders author', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    expect(screen.getByText('F. Scott Fitzgerald')).toBeInTheDocument();
  });

  it('renders status badge text', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    expect(screen.getByText('to-read')).toBeInTheDocument();
  });

  it('badge carries data-status matching book status', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    expect(screen.getByText('to-read')).toHaveAttribute('data-status', 'to-read');
  });

  it('accessible name combines title and author', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    expect(
      screen.getByRole('button', { name: 'The Great Gatsby by F. Scott Fitzgerald' })
    ).toBeInTheDocument();
  });

  it('calls onClick with book id on click', () => {
    const onClick = vi.fn();
    render(<BookCard book={book} onClick={onClick} />);
    fireEvent.click(screen.getByRole('button'));
    expect(onClick).toHaveBeenCalledWith('b1');
    expect(onClick).toHaveBeenCalledTimes(1);
  });

  it('calls onClick with book id on Enter keydown', () => {
    const onClick = vi.fn();
    render(<BookCard book={book} onClick={onClick} />);
    fireEvent.keyDown(screen.getByRole('button'), { key: 'Enter' });
    expect(onClick).toHaveBeenCalledWith('b1');
    expect(onClick).toHaveBeenCalledTimes(1);
  });

  it('does not call onClick on non-Enter keydown', () => {
    const onClick = vi.fn();
    render(<BookCard book={book} onClick={onClick} />);
    fireEvent.keyDown(screen.getByRole('button'), { key: ' ' });
    expect(onClick).not.toHaveBeenCalled();
  });
});

