import { render, screen, fireEvent } from '@testing-library/react';
import { describe, it, expect, vi } from 'vitest';
import { ChipBar } from './ChipBar';

const options = [
  { value: 'to-read', label: 'To Read' },
  { value: 'reading', label: 'Reading' },
  { value: 'read', label: 'Read' },
];

const allOption = { value: 'all', label: 'All' };

describe('ChipBar', () => {
  it('renders a chip for each option', () => {
    render(<ChipBar options={options} selected={[]} onSelectionChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'To Read' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Reading' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Read' })).toBeInTheDocument();
  });

  it('unselected chips have aria-pressed false', () => {
    render(<ChipBar options={options} selected={[]} onSelectionChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'To Read' })).toHaveAttribute('aria-pressed', 'false');
  });

  it('selected chips have aria-pressed true', () => {
    render(<ChipBar options={options} selected={['reading']} onSelectionChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'Reading' })).toHaveAttribute('aria-pressed', 'true');
    expect(screen.getByRole('button', { name: 'To Read' })).toHaveAttribute('aria-pressed', 'false');
  });

  it('clicking an unselected chip adds it to selection', () => {
    const onSelectionChange = vi.fn();
    render(
      <ChipBar options={options} selected={['reading']} onSelectionChange={onSelectionChange} />
    );
    fireEvent.click(screen.getByRole('button', { name: 'To Read' }));
    expect(onSelectionChange).toHaveBeenCalledTimes(1);
    expect(onSelectionChange).toHaveBeenCalledWith(
      expect.arrayContaining(['reading', 'to-read'])
    );
  });

  it('clicking a selected chip removes it from selection', () => {
    const onSelectionChange = vi.fn();
    render(
      <ChipBar options={options} selected={['reading', 'read']} onSelectionChange={onSelectionChange} />
    );
    fireEvent.click(screen.getByRole('button', { name: 'Reading' }));
    expect(onSelectionChange).toHaveBeenCalledTimes(1);
    const [nextSelected] = onSelectionChange.mock.calls[0];
    expect(nextSelected).not.toContain('reading');
    expect(nextSelected).toContain('read');
  });

  it('toggling the only selected chip yields empty selection', () => {
    const onSelectionChange = vi.fn();
    render(
      <ChipBar options={options} selected={['read']} onSelectionChange={onSelectionChange} />
    );
    fireEvent.click(screen.getByRole('button', { name: 'Read' }));
    expect(onSelectionChange).toHaveBeenCalledWith([]);
  });

  it('multiple chips can be selected simultaneously', () => {
    render(
      <ChipBar options={options} selected={['to-read', 'reading', 'read']} onSelectionChange={vi.fn()} />
    );
    options.forEach(({ label }) => {
      expect(screen.getByRole('button', { name: label })).toHaveAttribute('aria-pressed', 'true');
    });
  });

  describe('All chip', () => {
    it('All chip renders when allOption is provided', () => {
      render(
        <ChipBar options={options} selected={[]} onSelectionChange={vi.fn()} allOption={allOption} />
      );
      expect(screen.getByRole('button', { name: 'All' })).toBeInTheDocument();
    });

    it('All chip is pressed when nothing is selected', () => {
      render(
        <ChipBar options={options} selected={[]} onSelectionChange={vi.fn()} allOption={allOption} />
      );
      expect(screen.getByRole('button', { name: 'All' })).toHaveAttribute('aria-pressed', 'true');
    });

    it('All chip is not pressed when something is selected', () => {
      render(
        <ChipBar options={options} selected={['reading']} onSelectionChange={vi.fn()} allOption={allOption} />
      );
      expect(screen.getByRole('button', { name: 'All' })).toHaveAttribute('aria-pressed', 'false');
    });

    it('clicking All chip deselects all others', () => {
      const onSelectionChange = vi.fn();
      render(
        <ChipBar
          options={options}
          selected={['to-read', 'reading']}
          onSelectionChange={onSelectionChange}
          allOption={allOption}
        />
      );
      fireEvent.click(screen.getByRole('button', { name: 'All' }));
      expect(onSelectionChange).toHaveBeenCalledWith([]);
    });

    it('clicking All chip when already all deselected still calls with empty array', () => {
      const onSelectionChange = vi.fn();
      render(
        <ChipBar
          options={options}
          selected={[]}
          onSelectionChange={onSelectionChange}
          allOption={allOption}
        />
      );
      fireEvent.click(screen.getByRole('button', { name: 'All' }));
      expect(onSelectionChange).toHaveBeenCalledWith([]);
    });
  });
});
